import{c as t,Q as a,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"12-Rule Canon — Auto-load Patch Proposal (APPLY-gated)","description":"","frontmatter":{"title":"12-Rule Canon — Auto-load Patch Proposal (APPLY-gated)","date":"2026-06-04T00:00:00.000Z","status":"PROPOSAL — APPLY requires a gated session","branch":"feature/karpathy-mnilax-universalization","constraint":"§R1–§R12 conduct articles are NOT touched. Proposal only. Auto-load budget 18,455/19,000 (margin 545 B).","research":"2026-06-04-karpathy-mnilax-12-rule-universalization-research.md","ruleset":"2026-06-04-12-rule-universal-ruleset.md","type":"proposal"},"headers":[],"relativePath":"research/reports/archive/2026-06-04-12-rule-canon-patch-proposal.md","filePath":"research/reports/archive/2026-06-04-12-rule-canon-patch-proposal.md","lastUpdated":1785909234000}'),r={name:"research/reports/archive/2026-06-04-12-rule-canon-patch-proposal.md"};function s(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="_12-rule-canon-—-auto-load-patch-proposal" tabindex="-1">12-Rule Canon — Auto-load Patch Proposal <a class="header-anchor" href="#_12-rule-canon-—-auto-load-patch-proposal" aria-label="Permalink to &quot;12-Rule Canon — Auto-load Patch Proposal&quot;">​</a></h1><blockquote><p><strong>Scope guard.</strong> This is a <strong>proposal</strong>, not an applied change. The §R1–§R12 behavioral articles in <code>core.md</code> are <strong>not</strong> modified by any item here. APPLY is a separate gated session (per workspace rule: auto-load changes near the 19,000-byte cap are gated). Current: <strong>18,455/19,000, margin 545 B</strong>.</p></blockquote><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h2><p>Research surfaced 3 candidate gaps. Each was checked against existing auto-load text <strong>before</strong> proposing (R8: read before write; R2: don&#39;t build what exists). Result: <strong>1 APPLY-candidate, 1 ref-only, 1 NO-OP (already covered).</strong></p><hr><h2 id="p1-—-r6-universalization-note-apply-candidate" tabindex="-1">P1 — R6 universalization note (APPLY-candidate) <a class="header-anchor" href="#p1-—-r6-universalization-note-apply-candidate" aria-label="Permalink to &quot;P1 — R6 universalization note (APPLY-candidate)&quot;">​</a></h2><p><strong>Gap:</strong> <code>context-management.md:20-21</code> hardcodes <code>Per-task 4,000 / Per-session 30,000 tokens</code> with no signal that these are <em>this workspace&#39;s calibrated values</em>, not universal constants. The universalization research found R6 is the single biggest &quot;portability trap&quot; — anyone copying the canon to another harness/model would inherit the wrong numbers as if they were law.</p><p><strong>Proposed diff (context-management.md, after line 21):</strong></p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   - Per-task budget: **4,000 tokens**（單一工作上限）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   - Per-session budget: **30,000 tokens**（整個 session 上限）</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  - **數字為本 workspace 校準值，非普世常數**：跨 harness/模型移植時，原則（設明確預算 + breach 必 surface）不變，數字依模型與成本自訂。</span></span></code></pre></div><p><strong>Byte cost:</strong> ~150 B (CJK). Margin after: 545 − 150 ≈ <strong>395 B</strong> (within budget).</p><p><strong>Why auto-load and not ref-only:</strong> R6 is auto-load; the trap is <em>at the point the numbers are read</em>. A →See pointer wouldn&#39;t fire when someone copies the literal numbers. This is a 1-line inline note, not new knowledge.</p><p><strong>Falsifiable prediction:</strong></p><ul><li>After APPLY: <code>wc -c</code> total ≤ 18,955 (still &lt; 19,000).</li><li>§R count unchanged = 12 (<code>grep -c &#39;§R[0-9]&#39; core.md</code> unchanged).</li><li>R6 budget numbers (4000/30000) <strong>unchanged</strong> — only a note added.</li><li><code>bash scripts/healthcheck.sh</code> FAIL=0.</li><li><strong>Verify:</strong> <code>grep -n &quot;非普世常數&quot; .claude/rules/context-management.md</code> returns 1 line; <code>wc -c CLAUDE.md .claude/rules/*.md | tail -1</code>.</li></ul><hr><h2 id="p2-—-methodology-credibility-note-ref-only-not-auto-load" tabindex="-1">P2 — methodology credibility note (ref-only, NOT auto-load) <a class="header-anchor" href="#p2-—-methodology-credibility-note-ref-only-not-auto-load" aria-label="Permalink to &quot;P2 — methodology credibility note (ref-only, NOT auto-load)&quot;">​</a></h2><p><strong>Gap:</strong> <code>.claude/refs/karpathy-mnilax-best-solution.md</code> lineage cites &quot;41%→3% mistake rate&quot; and &quot;76%→52% compliance past 14 rules&quot; without flagging these are <strong>single-author self-reported, non-peer-reviewed, non-reproducible</strong> numbers. This is exactly the misattribution failure mode MEMORY already records (SELF-ROUTE 65%/39% wrong-sourced; enterprise-failure stat downgraded to LOW). Leaving it unflagged invites the same error on re-cite.</p><p><strong>Proposed change (ref file §規則演化 Lineage, NOT auto-load — zero byte impact on cap):</strong></p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-           50 tasks × 30 codebases × 6 weeks；41%→3% mistake rate</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+           50 tasks × 30 codebases × 6 weeks；41%→3% mistake rate</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+           [信度 MEDIUM：作者自報實驗，無公開資料集 / 非同儕審查，引用須標「作者自報」]</span></span></code></pre></div><p><strong>Byte cost:</strong> 0 on auto-load cap (on-demand ref). Safe to APPLY without gating the cap — but bundle with P1 for one atomic commit.</p><p><strong>Falsifiable prediction:</strong> <code>grep -n &quot;作者自報&quot; .claude/refs/karpathy-mnilax-best-solution.md</code> returns ≥1; auto-load <code>wc -c</code> total unchanged (ref not in cap).</p><hr><h2 id="p3-—-r12-information-withholding-no-op-—-already-covered" tabindex="-1">P3 — R12 &quot;information withholding&quot; (NO-OP — already covered) <a class="header-anchor" href="#p3-—-r12-information-withholding-no-op-—-already-covered" aria-label="Permalink to &quot;P3 — R12 &quot;information withholding&quot; (NO-OP — already covered)&quot;">​</a></h2><p><strong>Original hypothesis:</strong> MAST&#39;s &quot;Information withholding&quot; failure mode (not sharing partial-failure info) is a gap in R12.</p><p><strong>Check result (R8 before proposing):</strong> <code>core.md:69</code> already states:</p><blockquote><p>略過步驟／跳過驗證<strong>必須明示</strong>，不得以「完成」「成功」掩蓋靜默跳過。<strong>語氣可調，資訊不省。</strong></p></blockquote><p>&quot;資訊不省&quot; (information not omitted) + &quot;不得掩蓋靜默跳過&quot; <strong>already covers</strong> MAST information-withholding. <strong>No change needed.</strong> Proposing one would violate R2 (building what exists). Recorded as NO-OP for honesty.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Verdict</th><th>Auto-load byte Δ</th><th>APPLY gate</th></tr></thead><tbody><tr><td>P1 R6 universalization note</td><td>APPLY-candidate</td><td>+~150 B → 395 B margin</td><td>gated session</td></tr><tr><td>P2 methodology credibility note</td><td>APPLY-candidate (ref)</td><td>0 (on-demand)</td><td>bundle w/ P1</td></tr><tr><td>P3 R12 info-withholding</td><td><strong>NO-OP (covered)</strong></td><td>0</td><td>—</td></tr></tbody></table><p><strong>Net if both APPLY:</strong> auto-load 18,455 → ~18,605, margin 545 → ~395. §R1–§R12 articles <strong>untouched</strong>. R6 numbers <strong>unchanged</strong>. No conduct change — both items are <em>meta-notes</em> (one says &quot;these numbers are local,&quot; one says &quot;this stat is self-reported&quot;).</p><p><strong>Recommendation:</strong> APPLY P1+P2 together in a gated session if the user approves; both are honesty/portability guards, not behavior changes. P3 confirmed NO-OP.</p>`,31)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
